// Fetches a page's basic details (title, site name, description) automatically
// when a link is saved (SCN-001). If the page can't be reached or parsed, it
// falls back to a best-guess derived from the address so the link is still saved
// (SCN-010). Kept dependency-free: a tiny targeted HTML scan rather than a full
// DOM parser.

import { deriveFallbackMeta, hostOf } from "../public/lib.js";

const FETCH_TIMEOUT_MS = 4000;
const MAX_BYTES = 512 * 1024; // only need the <head>

function decodeEntities(s) {
  if (!s) return s;
  return s
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .trim();
}

function metaContent(html, patterns) {
  for (const re of patterns) {
    const m = html.match(re);
    if (m && m[1]) return decodeEntities(m[1]);
  }
  return "";
}

export function parseMetadata(html, url) {
  const fallback = deriveFallbackMeta(url);
  const host = hostOf(url);

  const ogTitle = metaContent(html, [
    /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i,
    /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:title["']/i,
  ]);
  const titleTag = (() => {
    const m = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
    return m ? decodeEntities(m[1].replace(/\s+/g, " ")) : "";
  })();
  const description = metaContent(html, [
    /<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i,
    /<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i,
    /<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i,
  ]);
  const siteName = metaContent(html, [
    /<meta[^>]+property=["']og:site_name["'][^>]+content=["']([^"']+)["']/i,
    /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:site_name["']/i,
  ]);

  const title = ogTitle || titleTag || fallback.title;
  return {
    host,
    title: title || fallback.title,
    site: siteName || fallback.site,
    description: description || "",
  };
}

// Returns { host, title, site, description }. Never throws; on any failure it
// returns the address-derived fallback.
export async function fetchMetadata(url, fetchImpl = globalThis.fetch) {
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
    let html = "";
    try {
      const res = await fetchImpl(url, {
        signal: controller.signal,
        redirect: "follow",
        headers: { "user-agent": "BookmarksApp/1.0 (+metadata)" },
      });
      if (!res.ok) throw new Error("status " + res.status);
      const ct = res.headers.get("content-type") || "";
      if (!/text\/html|application\/xhtml/i.test(ct)) throw new Error("not html");
      html = await readCapped(res);
    } finally {
      clearTimeout(timer);
    }
    return parseMetadata(html, url);
  } catch {
    return deriveFallbackMeta(url);
  }
}

async function readCapped(res) {
  if (!res.body || !res.body.getReader) return await res.text();
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let out = "";
  let total = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.length;
    out += decoder.decode(value, { stream: true });
    if (total >= MAX_BYTES || /<\/head>/i.test(out)) {
      try { await reader.cancel(); } catch { /* ignore */ }
      break;
    }
  }
  return out;
}
// Persistence layer. Bookmarks are stored as JSON on disk with atomic writes.
//
// Design decision: a JSON file store (rather than SQLite) keeps the dependency
// footprint pure-JS with no native build step or experimental flags, which is
// more than adequate for a single-user personal bookmark manager. The access is
// funnelled through this module so the storage engine can be swapped later
// without touching callers. See DESIGN-DECISIONS.md (DD-2).

import { readFileSync, writeFileSync, renameSync, mkdirSync, existsSync } from "node:fs";
import { dirname } from "node:path";

export class Store {
  constructor(file) {
    this.file = file;
    mkdirSync(dirname(file), { recursive: true });
    if (!existsSync(file)) this._writeAll([]);
  }

  _readAll() {
    try {
      return JSON.parse(readFileSync(this.file, "utf8")) || [];
    } catch {
      return [];
    }
  }

  _writeAll(items) {
    const tmp = this.file + ".tmp";
    writeFileSync(tmp, JSON.stringify(items, null, 2));
    renameSync(tmp, this.file); // atomic replace
  }

  // Newest first (SCN-001). Ties (same-millisecond saves) are broken by the
  // monotonic id so ordering is always deterministic.
  list() {
    return this._readAll().sort((a, b) => b.savedAt - a.savedAt || b.id - a.id);
  }

  findByKey(key) {
    return this._readAll().find((b) => b.urlKey === key) || null;
  }

  get(id) {
    return this._readAll().find((b) => b.id === id) || null;
  }

  insert(bookmark) {
    const items = this._readAll();
    items.push(bookmark);
    this._writeAll(items);
    return bookmark;
  }

  update(id, patch) {
    const items = this._readAll();
    const i = items.findIndex((b) => b.id === id);
    if (i === -1) return null;
    items[i] = { ...items[i], ...patch };
    this._writeAll(items);
    return items[i];
  }

  remove(id) {
    const items = this._readAll();
    const next = items.filter((b) => b.id !== id);
    if (next.length === items.length) return false;
    this._writeAll(next);
    return true;
  }
}
// HTTP server: serves the web client and a small JSON API.
// Listens on 0.0.0.0 so it is reachable in the shared review environment.

import express from "express";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { Store } from "./src/store.js";
import { BookmarkService } from "./src/bookmarks.js";

const __dirname = dirname(fileURLToPath(import.meta.url));

export function createApp(service) {
  const app = express();
  app.use(express.json());
  app.use(express.static(join(__dirname, "public")));

  app.get("/api/bookmarks", (req, res) => {
    res.json({ bookmarks: service.list() });
  });

  app.post("/api/bookmarks", async (req, res) => {
    const result = await service.create(req.body && req.body.url);
    if (result.ok) return res.status(201).json({ bookmark: result.bookmark });
    if (result.code === "invalid") {
      return res.status(400).json({ error: "invalid", message: "That doesn't look like a valid link." });
    }
    if (result.code === "duplicate") {
      return res.status(409).json({
        error: "duplicate",
        existing: result.existing,
        archived: result.archived,
      });
    }
    return res.status(500).json({ error: "unknown" });
  });

  app.patch("/api/bookmarks/:id", (req, res) => {
    const result = service.update(Number(req.params.id), req.body || {});
    if (result.ok) return res.json({ bookmark: result.bookmark });
    return res.status(404).json({ error: "not_found" });
  });

  app.delete("/api/bookmarks/:id", (req, res) => {
    const result = service.remove(Number(req.params.id));
    if (result.ok) return res.status(204).end();
    return res.status(404).json({ error: "not_found" });
  });

  return app;
}

// Start the server only when run directly (not when imported by tests).
const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const dataFile = process.env.DATA_FILE || join(__dirname, "data", "bookmarks.json");
  const service = new BookmarkService(new Store(dataFile));
  const port = Number(process.env.PORT || 4000);
  createApp(service).listen(port, "0.0.0.0", () => {
    console.log(`Bookmarks app listening on http://0.0.0.0:${port}`);
  });
}
